func (p *Parser) Scan() (r scanner.Token) {
	return p.sc.Scan()
}

// init initalizes 'p' with content in 'src', assuming it comes from 'name'.
// 'src' becomes "owned" by 'p'. init invalidates any pre-existing ASTs produced by 'p'. Mutating
// 'src' invalidates the current AST returned from any parsing function called after init.
func (p *Parser) init(name string, src []byte) (err error) {
	p.eof = false
	p.errBudget = 10
	// A new buffer, so the last AST stays intact, sized by the last one scaled to
	// this input: a reused parser skips most regrowth, and a small input after a
	// large one is not handed the large one's capacity.
	var hint int
	if n := len(p.src); n != 0 {
		hint = int(int64(len(p.buf)) * int64(len(src)) / int64(n))
	}
	p.buf = make([]int32, 0, hint+hint/8)
	p.src = src
	p.tok = scanner.Token{}
	p.tokIndex = 0
	p.sc = scanner.NewRecScanner(name, p.src, p.scan, int(white_space))
	return nil
}

